    val elements: List<PeriodicElement> = completeElements.map { element ->
        val study = studyElements.firstOrNull { it.number == element.number }
        element.copy(group = if (element.block == "f") 0 else element.group, examTip = study?.examTip.orEmpty())
    }

    /** Detached f-block rows; 0 means the group is not assigned here. */
    internal fun tablePosition(element: PeriodicElement): Pair<Int, Int> = when (element.number) {
        in 57..71 -> 8 to element.number - 54
        in 89..103 -> 9 to element.number - 86
        else -> element.period to element.group
    }
}
